import React, { useState, useEffect } from "react";
import "bootstrap/dist/css/bootstrap.min.css";
import axios from "axios";
import { useParams } from "react-router-dom";

const Aula = () => {
  const [aulas, setAulas] = useState([]);
  const [materiais, setMateriais] = useState([]);
  const [aulasAoVivo, setAulasAoVivo] = useState([]);
  const [curso, setCurso] = useState(null);
  const [carregando, setCarregando] = useState(true);
  const { cursoId } = useParams(); // Assumindo que o cursoId vem da URL

  // Carregar dados do curso, aulas e materiais
  useEffect(() => {
    const carregarDados = async () => {
      try {
        setCarregando(true);

        // Carregar dados do curso
        const cursoResponse = await private_api.get(`/cursos/${cursoId}`);
        setCurso(cursoResponse.data);

        // Carregar aulas gravadas
        const aulasResponse = await private_api.get(`/aulas/curso/${cursoId}`);
        setAulas(aulasResponse.data);

        // Carregar materiais de apoio
        const materiaisResponse = await private_api.get(
          `/materiais/curso/${cursoId}`
        );
        setMateriais(materiaisResponse.data);

        // Carregar aulas ao vivo (se necessário)
        const aulasAoVivoResponse = await private_api.get(
          `/aulas-ao-vivo/curso/${cursoId}`
        );
        setAulasAoVivo(aulasAoVivoResponse.data);
      } catch (error) {
        console.error("Erro ao carregar dados:", error);
      } finally {
        setCarregando(false);
      }
    };

    if (cursoId) {
      carregarDados();
    }
  }, [cursoId]);

  const handleDownloadAula = async (aulaId, aulaTitulo) => {
    try {
      // Cria um link temporário para forçar o download
      const downloadUrl = `${private_api.defaults.baseURL}aulas/download/${aulaId}`;
      const link = document.createElement("a");
      link.href = downloadUrl;
      link.setAttribute(
        "download",
        `${aulaTitulo.replace(/[^a-zA-Z0-9]/g, "_")}.mp4`
      );
      link.setAttribute("target", "_blank");
      document.body.appendChild(link);
      link.click();
      document.body.removeChild(link);
    } catch (error) {
      console.error("Erro ao baixar aula:", error);
      alert("Erro ao baixar a aula. Por favor, tente novamente.");
    }
  };

  const handleDownloadMaterial = async (materialId, materialNome) => {
    try {
      const downloadUrl = `${private_api.defaults.baseURL}materiais/download/${materialId}`;
      const link = document.createElement("a");
      link.href = downloadUrl;
      link.setAttribute("download", materialNome || "material");
      link.setAttribute("target", "_blank");
      document.body.appendChild(link);
      link.click();
      document.body.removeChild(link);
    } catch (error) {
      console.error("Erro ao baixar material:", error);
      alert("Erro ao baixar o material. Por favor, tente novamente.");
    }
  };

  return (
    <div
      className="container-fluid d-flex flex-column align-items-center"
      style={{
        backgroundColor: "#E7EFF4",
        minHeight: "100vh",
        padding: "20px",
      }}
    >
      <nav className="nav nav-tabs mb-3 bg-white p-2 w-75 d-flex justify-content-center">
        <a className="nav-link" href="#">
          Cursos
        </a>
        <a className="nav-link active" href="#">
          Aulas
        </a>
        <a className="nav-link" href="#">
          Avaliações
        </a>
      </nav>

      <h2 className="mb-3 text-center">Aulas {curso && `- ${curso.nome}`}</h2>

      {carregando ? (
        <div className="text-center my-4">
          <div className="spinner-border text-primary" role="status">
            <span className="visually-hidden">Carregando...</span>
          </div>
        </div>
      ) : (
        <>
          <div className="row w-75">
            <div className="col-md-6">
              <h4 className="text-center">Aulas Ao Vivo</h4>
              {aulasAoVivo.length > 0 ? (
                <div className="card p-3 mb-3">
                  <div className="list-group">
                    {aulasAoVivo.map((aula) => (
                      <div key={aula.salaId} className="list-group-item">
                        <div className="d-flex justify-content-between align-items-center">
                          <span>{aula.nome}</span>
                          <button
                            className="btn btn-sm btn-success"
                            onClick={() => window.open(aula.url, "_blank")}
                          >
                            Entrar na Aula
                          </button>
                        </div>
                      </div>
                    ))}
                  </div>
                </div>
              ) : (
                <div className="alert alert-info">
                  Nenhuma aula ao vivo agendada para este curso
                </div>
              )}
            </div>
            <div className="col-md-6">
              <h4 className="text-center">Aulas Gravadas</h4>
              {aulas.length > 0 ? (
                <div className="list-group">
                  {aulas.map((aula) => (
                    <button
                      key={aula.id}
                      className="list-group-item list-group-item-action d-flex justify-content-between align-items-center"
                      onClick={() => handleDownloadAula(aula.id, aula.titulo)}
                    >
                      {aula.titulo}
                      <span className="badge bg-primary rounded-pill">
                        Assistir
                      </span>
                    </button>
                  ))}
                </div>
              ) : (
                <div className="alert alert-info">
                  Nenhuma aula gravada disponível para este curso
                </div>
              )}
            </div>
          </div>

          <div className="mt-4 w-75">
            <h4 className="text-center">Material de Apoio</h4>
            <div className="card p-3">
              {materiais.length > 0 ? (
                <div className="list-group">
                  {materiais.map((material) => (
                    <button
                      key={material.id}
                      className="list-group-item list-group-item-action d-flex justify-content-between align-items-center"
                      onClick={() =>
                        handleDownloadMaterial(material.id, material.nome)
                      }
                    >
                      {material.nome || "Material sem nome"}
                      <span className="badge bg-primary rounded-pill">
                        Baixar
                      </span>
                    </button>
                  ))}
                </div>
              ) : (
                <div className="alert alert-info">
                  Nenhum material de apoio disponível para este curso
                </div>
              )}
            </div>
          </div>
        </>
      )}
    </div>
  );
};

export default Aula;
